SELECT t.title, n.name, cn.name, COUNT(*) FROM title as t, movie_keyword as mk, keyword as k, movie_companies as mc, company_name as cn, company_type as ct, kind_type as kt, cast_info as ci, name as n, role_type as rt WHERE t.id = mk.movie_id AND t.id = mc.movie_id AND t.id = ci.movie_id AND ci.movie_id = mc.movie_id AND ci.movie_id = mk.movie_id AND mk.movie_id = mc.movie_id AND k.id = mk.keyword_id AND cn.id = mc.company_id AND ct.id = mc.company_type_id AND kt.id = t.kind_id AND ci.person_id = n.id AND ci.role_id = rt.id AND (UPPER(t.title) LIKE UPPER('%1.15%')) AND (UPPER(n.surname_pcode) LIKE UPPER('%a13%')) AND (UPPER(cn.name) LIKE UPPER('%ab%')) AND (kt.kind IN ('episode')) AND (rt.role IN ('actor','actress','miscellaneous crew')) GROUP BY 1, 2, 3 ORDER BY COUNT(*) DESC
